b('const PC = ["#f59e0b", "#ef4444", "#059669", "#3b82f6", "#8b5cf6", "#06b6d4", "#ec4899", "#14b8a6"]')
b('')
b('// ── Utilities ──')
b('function seededRandom(seed: number): number { const x = Math.sin(seed * 9301 + 49297) * 233280; return x - Math.floor(x) }')
b('function ri(min: number, max: number, seed: number): number { return Math.floor(seededRandom(seed) * (max - min + 1)) + min }')
b('function pick<T>(arr: readonly T[], seed: number): T { return arr[Math.floor(seededRandom(seed) * arr.length)] }')
b('')
b('// ── Visual Components ──')
b('function VehicleBadge({ type }: { type: string }) {')
b('  const cols: Record<string, string> = { bike: "bg-amber-100 text-amber-700 dark:bg-amber-900/30", van: "bg-blue-100 text-blue-700 dark:bg-blue-900/30", truck: "bg-violet-100 text-violet-700 dark:bg-violet-900/30", "e Rickshaw": "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30", drones: "bg-sky-100 text-sky-700 dark:bg-sky-900/30" }')
b('  return <span className={"lmo-vehicle-badge inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-semibold " + (cols[type] || "bg-gray-100 text-gray-700")}>{VEHICLE_EMOJI[type] || "\\u2022"} {type}</span>')
b('}')
b('')
b('function DeliveryStatusBadge({ status }: { status: string }) {')
b('  const cols: Record<string, string> = { in_transit: "lmo-status-transit bg-blue-100 text-blue-700 dark:bg-blue-900/30", delivered: "lmo-status-delivered bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 shadow-[0_0_6px_rgba(5,150,105,0.3)]", failed: "lmo-status-failed bg-red-100 text-red-700 dark:bg-red-900/30 shadow-[0_0_8px_rgba(220,38,38,0.4)]", rescheduled: "lmo-status-resched bg-amber-100 text-amber-700 dark:bg-amber-900/30", picked_up: "lmo-status-picked bg-violet-100 text-violet-700 dark:bg-violet-900/30", out_for_delivery: "lmo-status-ofd bg-cyan-100 text-cyan-700 dark:bg-cyan-900/30" }')
b('  const icons: Record<string, React.ReactNode> = { in_transit: <Truck className="w-3 h-3" />, delivered: <CheckCircle2 className="w-3 h-3" />, failed: <AlertTriangle className="w-3 h-3" />, rescheduled: <Clock className="w-3 h-3" />, picked_up: <Package className="w-3 h-3" />, out_for_delivery: <Navigation className="w-3 h-3" /> }')
b('  return <span className={"lmo-delivery-badge inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-semibold " + (cols[status] || "")}>{icons[status]} {status.replace(/_/g, " ")}</span>')
b('}')
b('')
b('function SLABadge({ value }: { value: number }) {')
b('  const col = value >= 95 ? TH.ok : value >= 85 ? TH.warn : TH.err')
b('  return <span className="lmo-sla-badge inline-flex items-center gap-1 text-[10px] font-bold" style={{ color: col }}>{value}%</span>')
b('}')
b('')
b('function EffBar({ value }: { value: number }) {')
b('  const col = value >= 80 ? TH.ok : value >= 50 ? TH.warn : TH.err')
b('  return <div className="lmo-eff-bar flex items-center gap-1.5"><div className="w-16 h-2 rounded-full bg-gray-200 dark:bg-gray-700 overflow-hidden"><div className="h-full rounded-full transition-all" style={{ width: value + "%", backgroundColor: col }}/></div><span className="text-[10px] font-bold" style={{ color: col }}>{value}%</span></div>')
b('}')
b('')
b('function TrendIndicator({ value }: { value: number }) {')
b('  const pos = value > 0')
b('  const col = pos ? TH.ok : TH.err')
b('  return <span className="lmo-trend inline-flex items-center gap-0.5 text-[10px] font-semibold" style={{ color: col }}>{pos ? <TrendingUp className="w-3 h-3" /> : <TrendingDown className="w-3 h-3" />}{Math.abs(value).toFixed(1)}%</span>')
b('}')
b('')
b('function CityBadge({ city }: { city: string }) {')
