b('}')
b('')
b('function FuelTile({ liters, cost, saved }: { liters: number; cost: number; saved: number }) {')
b('  return <div className="lmo-fuel-tile p-2 rounded-lg border border-amber-200 dark:border-amber-800"><div className="flex items-center gap-1 mb-1"><Fuel className="w-3 h-3 text-amber-500"/><span className="text-[10px] font-medium">Fuel</span></div><div className="text-xs font-bold">{liters}L</div><div className="text-[10px] text-muted-foreground">{"\\u20b9"}{cost}</div>{saved > 0 && <div className="text-[10px] text-emerald-600 font-medium">Saved {"\\u20b9"}{saved}</div>}</div>')
b('}')
b('')
b('function StarRating({ value }: { value: number }) {')
b('  return <div className="lmo-star-rating flex items-center gap-0.5">{Array.from({ length: 5 }, (_, i) => <Star key={i} className={"w-3 h-3 " + (i < value ? "text-amber-400 fill-amber-400" : "text-gray-300")}/>)}</div>')
b('}')
b('')
b('function DeliveryRing({ delivered, total }: { delivered: number; total: number }) {')
b('  const pct = Math.round((delivered / total) * 100)')
b('  const r = 18, circ = 2 * Math.PI * r, offset = circ - (pct / 100) * circ')
b('  const col = pct >= 95 ? TH.ok : pct >= 85 ? TH.warn : TH.err')
b('  return <div className="lmo-delivery-ring flex flex-col items-center gap-1"><svg width={48} height={48} className="-rotate-90"><circle cx={24} cy={24} r={r} fill="none" stroke="currentColor" strokeWidth={3} className="text-gray-200 dark:text-gray-700"/><circle cx={24} cy={24} r={r} fill="none" stroke={col} strokeWidth={3} strokeDasharray={circ} strokeDashoffset={offset} strokeLinecap="round" className="transition-all"/></svg><span className="text-[10px] font-bold" style={{ color: col }}>{pct}%</span><span className="text-[9px] text-muted-foreground">{delivered}/{total}</span></div>')
b('}')
b('')
b('function CostTile({ label, value }: { label: string; value: number }) {')
b('  return <div className="lmo-cost-tile text-center p-2 rounded-lg bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800"><div className="text-xs font-bold text-red-600">{"\\u20b9"}{value.toLocaleString()}</div><div className="text-[10px] text-muted-foreground">{label}</div></div>')
b('}')
b('')
b('// ── Data Generators ──')
b('function genDeliveries() {')
b('  return Array.from({ length: 80 }, (_, i) => {')
b('    const st = pick(DELIVERY_STATUS, i * 3 + 1)')
b('    return {')
b('      id: "ORD-" + String(i + 1).padStart(6, "0"),')
b('      customer: pick(["Rahul Sharma", "Priya Patel", "Amit Kumar", "Sneha Gupta", "Vikram Singh", "Anjali Reddy", "Karan Mehta", "Divya Iyer", "Suresh Nair", "Meera Joshi", "Arjun Das", "Pooja Rao", "Rajesh Pillai", "Neha Bose", "Sunil Kulkarni"], i * 3 + 2),')
b('      city: pick(CITIES, i * 3 + 3),')
b('      zone: pick(ZONES, i * 3 + 4),')
b('      vehicle: pick(VEHICLE_TYPES, i * 3 + 5),')
b('      status: st,')
b('      eta: String(ri(5, 240, i + 7)) + " min",')
b('      distance: +(ri(1, 45, i + 11) / 10).toFixed(1),')
b('      cost: ri(30, 500, i + 13),')
b('      weight: ri(1, 50, i + 17),')
b('      priority: pick(["high", "medium", "low"], i + 19),')
b('      rating: ri(1, 5, i + 23),')
b('      attempts: st === "failed" ? ri(2, 5, i + 29) : 1,')
b('      driver: pick(["Ravi K.", "Suresh M.", "Manoj T.", "Arun D.", "Deepak S.", "Ramesh G.", "Vijay P.", "Ganesh B."], i + 31),')
b('      timestamp: "2026-07-" + String(ri(1, 30, i + 37)).padStart(2, "0") + " " + String(ri(8, 21, i + 41)).padStart(2, "0") + ":" + String(ri(0, 59, i + 43)).padStart(2, "0")')
b('    }')
b('  })')
b('}')
b('')
b('function genFleet() {')
b('  return Array.from({ length: 40 }, (_, i) => {')
b('    return {')
b('      id: "VH-" + String(i + 1).padStart(4, "0"),')
b('      type: pick(VEHICLE_TYPES, i * 3 + 1),')
b('      driver: pick(["Ravi K.", "Suresh M.", "Manoj T.", "Arun D.", "Deepak S.", "Ramesh G.", "Vijay P.", "Ganesh B.", "Kiran J.", "Prasad H."], i * 3 + 2),')
b('      city: pick(CITIES, i * 3 + 3),')
b('      zone: pick(ZONES, i * 3 + 4),')
b('      capacity: ri(10, 500, i + 7),')
b('      load: ri(5, 480, i + 11),')
b('      efficiency: ri(45, 98, i + 13),')
b('      fuelLevel: ri(10, 100, i + 17),')
b('      deliveries: ri(5, 60, i + 19),')
b('      delivered: ri(3, 58, i + 23),')
b('      avgTime: ri(15, 90, i + 29),')
b('      rating: +(ri(30, 50, i + 31) / 10).toFixed(1),')
b('      status: pick(["active", "active", "active", "break", "maintenance", "charging"], i + 37),')
b('      battery: pick(VEHICLE_TYPES, i + 1) === "bike" || pick(VEHICLE_TYPES, i + 1) === "e Rickshaw" ? ri(20, 100, i + 41) : null,')
b('      kmToday: ri(20, 200, i + 43)')
b('    }')
b('  })')
b('}')
b('')
b('function genRoutes() {')
b('  return Array.from({ length: 30 }, (_, i) => {')
b('    return {')
b('      id: "RT-" + String(i + 1).padStart(4, "0"),')
b('      name: pick(["Metro Express", "Suburban Sprint", "Highway Direct", "City Loop", "Rapid Rural", "Downtown Dash", "Airport Shuttle", "Market Run", "Industrial Route", "Coastal Connect", "Hill Station Link", "Campus Circuit", "Hospitality Line", "Mall Express", "Residential Route"], i * 3 + 1),')
b('      city: pick(CITIES, i * 3 + 2),')
b('      stops: ri(5, 25, i + 7),')
b('      distance: ri(10, 120, i + 11),')
b('      time: ri(30, 480, i + 13),')
b('      cost: ri(200, 3000, i + 17),')
b('      efficiency: ri(50, 98, i + 19),')
b('      deliveries: ri(10, 80, i + 23),')
b('      fuelUsed: ri(5, 50, i + 29),')
b('      co2Saved: ri(2, 30, i + 31),')
b('      status: pick(["active", "active", "active", "delayed", "cancelled"], i + 37),')
b('      vehicles: ri(2, 15, i + 41)')
b('    }')
b('  })')
b('}')
b('')
b('function genCharts() {')
b('  const daily = MO.map((m, i) => ({ month: m, deliveries: ri(2000, 12000, i + 101), delivered: ri(1800, 11500, i + 151), failed: ri(20, 500, i + 201), onTime: ri(1500, 11000, i + 251) }))')
b('  const vehicleDist = VEHICLE_TYPES.map((v, i) => ({ type: v, count: ri(5, 20, i + 301), avgEff: ri(60, 95, i + 351) }))')
b('  const zonePerf = ZONES.map((z, i) => ({ zone: z, sla: ri(80, 98, i + 401), cost: ri(100, 500, i + 451), satisfaction: ri(3, 5, i + 501) }))')
b('  const costTrend = MO.map((m, i) => ({ month: m, fuel: ri(50000, 200000, i + 551), labor: ri(80000, 300000, i + 601), penalty: ri(5000, 50000, i + 651) }))')
b('  return { daily, vehicleDist, zonePerf, costTrend }')
b('}')
b('')
b('// ── Main Component ──')
b('export default function LastMileOptimizationProView() {')
b('  const [tab, setTab] = useState("dashboard")')
b('  const [search, setSearch] = useState("")')
b('  const [detail, setDetail] = useState<Record<string, unknown> | null>(null)')
b('  const [sortField, setSortField] = useState("id")')
b('  const [sortDir, setSortDir] = useState<"asc" | "desc">("asc")')
b('')
b('  const deliveries = useMemo(() => genDeliveries(), [])')
b('  const fleet = useMemo(() => genFleet(), [])')
b('  const routes = useMemo(() => genRoutes(), [])')
b('  const charts = useMemo(() => genCharts(), [])')
b('')
b('  const toggleSort = (f: string) => { if (sortField === f) setSortDir(d => d === "asc" ? "desc" : "asc"); else { setSortField(f); setSortDir("asc") } }')
b('  const sortIcon = (f: string) => sortField === f ? (sortDir === "asc" ? "\\u2191" : "\\u2193") : ""')
b('')
b('  const filterDeliveries = useMemo(() => {')
b('    if (!search) return deliveries')
b('    const lq = search.toLowerCase()')
b('    return deliveries.filter(d => Object.values(d).some(v => typeof v === "string" && v.toLowerCase().includes(lq)))')
b('  }, [deliveries, search])')
b('')
b('  const sortedDeliveries = useMemo(() => [...filterDeliveries].sort((a, b) => { const va = a[sortField as keyof typeof a], vb = b[sortField as keyof typeof b]; if (va == null || vb == null) return 0; const cmp = String(va).localeCompare(String(vb), undefined, { numeric: true }); return sortDir === "asc" ? cmp : -cmp }), [filterDeliveries, sortField, sortDir])')
b('')
b('  const filterFleet = useMemo(() => {')
b('    if (!search) return fleet')
b('    const lq = search.toLowerCase()')
b('    return fleet.filter(f => Object.values(f).some(v => typeof v === "string" && v.toLowerCase().includes(lq)))')
b('  }, [fleet, search])')
b('')
b('  // Computed KPIs')
b('  const totalDelivered = deliveries.filter(d => d.status === "delivered").length')
b('  const totalFailed = deliveries.filter(d => d.status === "failed").length')
b('  const inTransit = deliveries.filter(d => d.status === "in_transit" || d.status === "out_for_delivery").length')
b('  const avgRating = +(fleet.reduce((s, f) => s + f.rating, 0) / fleet.length).toFixed(1)')
b('  const slaRate = Math.round((totalDelivered / Math.max(1, totalDelivered + totalFailed)) * 100)')
b('')
b('  const handleRefresh = () => { setSearch(""); setSortField("id"); setSortDir("asc") }')
b('')
b('  const [activeFilters, setActiveFilters] = useState<Record<string, string[]>>({})')
b('  const toggleFilter = (group: string, value: string) => {')
b('    setActiveFilters(prev => {')
b('      const cur = prev[group] || []')
b('      const next = cur.includes(value) ? cur.filter(v => v !== value) : [...cur, value]')
b('      if (next.length === 0) { const { [group]: _, ...rest } = prev; return rest }')
b('      return { ...prev, [group]: next }')
b('    })')
b('  }')
b('  const clearAllFilters = () => setActiveFilters({})')
b('  const totalActiveFilters = Object.values(activeFilters).reduce((s, v) => s + v.length, 0)')
b('')
b('  const deliveryFilterGroups = useMemo(() => {')
b('    const statusCounts: Record<string, number> = {}')
b('    const vehicleCounts: Record<string, number> = {}')
b('    const cityCounts: Record<string, number> = {}')
b('    deliveries.forEach(d => { statusCounts[d.status] = (statusCounts[d.status] || 0) + 1; vehicleCounts[d.vehicle] = (vehicleCounts[d.vehicle] || 0) + 1; cityCounts[d.city] = (cityCounts[d.city] || 0) + 1 })')
b('    return [')
b('      { key: "status", label: "Status", options: Object.entries(statusCounts).map(([value, count]) => ({ value: value.replace(/_/g, " "), count })).sort((a, b) => b.count - a.count) },')
b('      { key: "vehicle", label: "Vehicle", options: Object.entries(vehicleCounts).map(([value, count]) => ({ value, count })).sort((a, b) => b.count - a.count) },')
b('      { key: "city", label: "City", options: Object.entries(cityCounts).map(([value, count]) => ({ value, count })).sort((a, b) => b.count - a.count).slice(0, 8) }')
b('    ]')
b('  }, [deliveries])')
b('')
b('  const tab0 = (')
b('    <div className="space-y-4">')
b('      <div className="grid grid-cols-2 md:grid-cols-4 gap-3">')
b('        <KpiTile label="Total Deliveries" value={deliveries.length.toString()} icon={<Package className="w-4 h-4 text-amber-500"/>} trend={12.5} color={TH.pri}/>')
b('        <KpiTile label="In Transit" value={inTransit.toString()} icon={<Truck className="w-4 h-4 text-blue-500"/>} trend={3.2} color="#3b82f6"/>')
b('        <KpiTile label="SLA Rate" value={slaRate + "%"} icon={<CheckCircle2 className="w-4 h-4 text-emerald-500"/>} trend={1.8} color={TH.ok}/>')
b('        <KpiTile label="Failed" value={totalFailed.toString()} icon={<AlertTriangle className="w-4 h-4 text-red-500"/>} trend={-8.3} color={TH.err}/>')
b('      </div>')
b('      <div className="grid grid-cols-2 md:grid-cols-4 gap-3">')
b('        <DeliveryRing delivered={totalDelivered} total={deliveries.length}/>')
b('        <DeliveryRing delivered={fleet.reduce((s, f) => s + f.delivered, 0)} total={fleet.reduce((s, f) => s + f.deliveries, 0)}/>')
b('        <div className="lmo-fleet-summary text-center p-3"><div className="text-2xl font-bold text-amber-600">{fleet.length}</div><div className="text-[10px] text-muted-foreground">Active Vehicles</div><div className="text-xs text-emerald-600 font-medium mt-1">Rating: {avgRating}/5</div></div>')
b('        <div className="lmo-zone-summary text-center p-3"><div className="text-2xl font-bold text-violet-600">{routes.length}</div><div className="text-[10px] text-muted-foreground">Active Routes</div><div className="text-xs text-cyan-600 font-medium mt-1">{routes.reduce((s, r) => s + r.vehicles, 0)} vehicles assigned</div></div>')
b('      </div>')
b('      <div className="grid grid-cols-1 md:grid-cols-2 gap-3">')
b('        <Card className="lmo-chart-card glass-subtle"><CardHeader className="pb-1"><CardTitle className="text-xs">Daily Delivery Volume</CardTitle></CardHeader><CardContent><AreaChart data={charts.daily} height={200}><CartesianGrid strokeDasharray="3 3" opacity={0.3}/><XAxis dataKey="month" tick={{ fontSize: 10 }}/><YAxis tick={{ fontSize: 10 }}/><Tooltip contentStyle={{ fontSize: 10 }}/><Area type="monotone" dataKey="deliveries" stroke={TH.pri} fill={TH.pri} fillOpacity={0.2}/><Area type="monotone" dataKey="delivered" stroke={TH.ok} fill={TH.ok} fillOpacity={0.15}/><Line type="monotone" dataKey="failed" stroke={TH.err} strokeWidth={2} dot={{ r: 3 }}/></AreaChart></CardContent></Card>')
b('        <Card className="lmo-chart-card glass-subtle"><CardHeader className="pb-1"><CardTitle className="text-xs">Vehicle Distribution & Efficiency</CardTitle></CardHeader><CardContent><BarChart data={charts.vehicleDist} height={200}><CartesianGrid strokeDasharray="3 3" opacity={0.3}/><XAxis dataKey="type" tick={{ fontSize: 10 }}/><YAxis tick={{ fontSize: 10 }}/><Tooltip contentStyle={{ fontSize: 10 }}/><Bar dataKey="count" fill={TH.pri} radius={[2, 2, 0, 0]}/><Bar dataKey="avgEff" fill={TH.ok} radius={[2, 2, 0, 0]}/></BarChart></CardContent></Card>')
b('        <Card className="lmo-chart-card glass-subtle"><CardHeader className="pb-1"><CardTitle className="text-xs">Zone Performance</CardTitle></CardHeader><CardContent><BarChart data={charts.zonePerf} height={200}><CartesianGrid strokeDasharray="3 3" opacity={0.3}/><XAxis dataKey="zone" tick={{ fontSize: 10 }}/><YAxis tick={{ fontSize: 10 }}/><Tooltip contentStyle={{ fontSize: 10 }}/><Bar dataKey="sla" fill={TH.sec} radius={[2, 2, 0, 0]}/><Bar dataKey="satisfaction" fill={TH.ok} radius={[2, 2, 0, 0]}/></BarChart></CardContent></Card>')
b('        <Card className="lmo-chart-card glass-subtle"><CardHeader className="pb-1"><CardTitle className="text-xs">Cost Breakdown Trend</CardTitle></CardHeader><CardContent><LineChart data={charts.costTrend} height={200}><CartesianGrid strokeDasharray="3 3" opacity={0.3}/><XAxis dataKey="month" tick={{ fontSize: 10 }}/><YAxis tick={{ fontSize: 10 }}/><Tooltip contentStyle={{ fontSize: 10 }}/><Line type="monotone" dataKey="fuel" stroke={TH.pri} strokeWidth={2} dot={{ r: 3 }}/><Line type="monotone" dataKey="labor" stroke={TH.sec} strokeWidth={2} strokeDasharray="5 5" dot={{ r: 3 }}/><Line type="monotone" dataKey="penalty" stroke={TH.err} strokeWidth={2} dot={{ r: 3 }}/></LineChart></CardContent></Card>')
b('      </div>')
b('    </div>')
b('  )')
b('')
b('  const tab1 = (')
b('    <div className="space-y-3">')
b('      <ModuleBreadcrumb items={[{ label: "Logistics" }, { label: "Last Mile" }, { label: "Deliveries" }]}/>')
b('      <SearchFilterToolbar searchQuery={search} onSearchChange={setSearch} onClearSearch={() => setSearch("")} activeFilters={activeFilters} filterGroups={deliveryFilterGroups} onToggleFilter={toggleFilter} onClearAllFilters={clearAllFilters} totalItems={deliveries.length} filteredCount={filterDeliveries.length} onRefresh={handleRefresh} placeholder="Search orders, customers, drivers..." />')
b('      <div className="rounded-lg border overflow-auto max-h-[calc(100vh-340px)]">')
b('        <table className="lmo-table w-full text-xs"><thead className="bg-amber-50 dark:bg-amber-900/20 sticky top-0"><tr><th className="p-2 text-left cursor-pointer select-none" onClick={() => toggleSort("id")}>Order ID {sortIcon("id")}</th><th className="p-2 text-left">Customer</th><th className="p-2 text-left">City</th><th className="p-2 text-left">Vehicle</th><th className="p-2 text-left">Status</th><th className="p-2 text-left">ETA</th><th className="p-2 text-right">Distance</th><th className="p-2 text-right">Cost</th><th className="p-2 text-left">Priority</th><th className="p-2 text-left">Driver</th></tr></thead>')
b('        <tbody>{sortedDeliveries.map(d => <tr key={d.id} className="lmo-table-row border-t hover:bg-amber-50/50 dark:hover:bg-amber-900/10 cursor-pointer" onClick={() => setDetail(d as unknown as Record<string, unknown>)}><td className="p-2 font-mono">{d.id}</td><td className="p-2 font-medium">{d.customer}</td><td className="p-2"><CityBadge city={d.city}/></td><td className="p-2"><VehicleBadge type={d.vehicle}/></td><td className="p-2"><DeliveryStatusBadge status={d.status}/></td><td className="p-2">{d.eta}</td><td className="p-2 text-right">{d.distance} km</td><td className="p-2 text-right">{"\\u20b9"}{d.cost}</td><td className="p-2"><span className={"lmo-priority-badge inline-flex px-1.5 py-0.5 rounded text-[10px] font-medium " + (d.priority === "high" ? "bg-red-100 text-red-700" : d.priority === "medium" ? "bg-amber-100 text-amber-700" : "bg-emerald-100 text-emerald-700")}>{d.priority}</span></td><td className="p-2 text-[10px]">{d.driver}</td></tr>)}</tbody></table>')
b('      </div>')
b('      <div className="flex items-center justify-between text-[10px] text-muted-foreground"><span>Showing {sortedDeliveries.length} of {deliveries.length} deliveries</span>{totalActiveFilters > 0 && <span>{totalActiveFilters} filters active</span>}</div>')
b('    </div>')
b('  )')
b('')
b('  const tab2 = (')
b('    <div className="space-y-4">')
b('      <ModuleBreadcrumb items={[{ label: "Logistics" }, { label: "Last Mile" }, { label: "Fleet" }]}/>')
b('      <SearchFilterToolbar searchQuery={search} onSearchChange={setSearch} onClearSearch={() => setSearch("")} activeFilters={activeFilters} filterGroups={[]} onToggleFilter={toggleFilter} onClearAllFilters={clearAllFilters} totalItems={fleet.length} filteredCount={filterFleet.length} onRefresh={handleRefresh} placeholder="Search vehicles, drivers..." />')
b('      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">')
b('        {filterFleet.map(f => (')
b('          <Card key={f.id} className={"lmo-fleet-card glass-subtle hover:shadow-lg transition-shadow " + (f.status === "active" ? "border-emerald-300 dark:border-emerald-700" : f.status === "maintenance" ? "border-amber-300 dark:border-amber-700" : "")}>')
b('            <CardContent className="p-3 space-y-2">')
b('              <div className="flex items-center justify-between"><span className="font-semibold text-xs">{f.id}</span><VehicleBadge type={f.type}/></div>')
b('              <div className="flex items-center justify-between text-[10px]"><span className="text-muted-foreground">Driver</span><span className="font-medium">{f.driver}</span></div>')
b('              <div className="flex items-center justify-between text-[10px]"><span className="text-muted-foreground">City</span><CityBadge city={f.city}/></div>')
b('              <div className="grid grid-cols-3 gap-1.5"><ValueTile label="Capacity" value={f.capacity}/><ValueTile label="Load" value={f.load}/><EffBar value={Math.round((f.load / f.capacity) * 100)}/></div>')
b('              <div className="flex items-center justify-between text-[10px]"><span className="text-muted-foreground">Efficiency</span><EffBar value={f.efficiency}/></div>')
b('              <div className="flex items-center justify-between text-[10px]"><span className="text-muted-foreground">Fuel</span><div className="flex items-center gap-1"><div className="w-10 h-2 rounded-full bg-gray-200 dark:bg-gray-700 overflow-hidden"><div className="h-full rounded-full" style={{ width: f.fuelLevel + "%", backgroundColor: f.fuelLevel <= 20 ? TH.err : f.fuelLevel <= 50 ? TH.warn : TH.ok }}/></div><span className="text-[10px]">{f.fuelLevel}%</span></div></div>')
b('              <div className="flex items-center justify-between text-[10px]"><span className="text-muted-foreground">Deliveries</span><DeliveryRing delivered={f.delivered} total={f.deliveries}/></div>')
b('              <div className="flex items-center justify-between text-[10px]"><span className="text-muted-foreground">Rating</span><StarRating value={Math.round(f.rating)}/></div>')
b('              <div className="flex items-center justify-between"><span className={"lmo-veh-status inline-flex px-1.5 py-0.5 rounded text-[10px] font-medium " + (f.status === "active" ? "bg-emerald-100 text-emerald-700" : f.status === "break" ? "bg-amber-100 text-amber-700" : f.status === "maintenance" ? "bg-red-100 text-red-700" : f.status === "charging" ? "bg-cyan-100 text-cyan-700" : "bg-gray-100 text-gray-600")}>{f.status}</span><span className="text-[10px] text-muted-foreground">{f.kmToday} km today</span></div>')
b('            </CardContent>')
b('          </Card>')
b('        ))}')
b('      </div>')
b('    </div>')
b('  )')
b('')
b('  const tab3 = (')
b('    <div className="space-y-3">')
b('      <ModuleBreadcrumb items={[{ label: "Logistics" }, { label: "Last Mile" }, { label: "Routes" }]}/>')
b('      <SearchFilterToolbar searchQuery={search} onSearchChange={setSearch} onClearSearch={() => setSearch("")} activeFilters={activeFilters} filterGroups={[]} onToggleFilter={toggleFilter} onClearAllFilters={clearAllFilters} totalItems={routes.length} filteredCount={routes.length} onRefresh={handleRefresh} placeholder="Search routes..." />')
b('      <div className="rounded-lg border overflow-auto max-h-[calc(100vh-340px)]">')
b('        <table className="lmo-table w-full text-xs"><thead className="bg-violet-50 dark:bg-violet-900/20 sticky top-0"><tr><th className="p-2 text-left cursor-pointer select-none" onClick={() => toggleSort("id")}>ID {sortIcon("id")}</th><th className="p-2 text-left">Route Name</th><th className="p-2 text-left">City</th><th className="p-2 text-right">Stops</th><th className="p-2 text-right">Distance</th><th className="p-2 text-right">Time</th><th className="p-2 text-left">Efficiency</th><th className="p-2 text-right">Deliveries</th><th className="p-2 text-left">CO2 Saved</th><th className="p-2 text-left">Status</th></tr></thead>')
b('        <tbody>{routes.map(r => <tr key={r.id} className="lmo-table-row border-t hover:bg-violet-50/50 dark:hover:bg-violet-900/10 cursor-pointer" onClick={() => setDetail(r as unknown as Record<string, unknown>)}><td className="p-2 font-mono">{r.id}</td><td className="p-2 font-medium">{r.name}</td><td className="p-2"><CityBadge city={r.city}/></td><td className="p-2 text-right">{r.stops}</td><td className="p-2 text-right">{r.distance} km</td><td className="p-2 text-right">{r.time} min</td><td className="p-2"><EffBar value={r.efficiency}/></td><td className="p-2 text-right">{r.deliveries}</td><td className="p-2"><span className="text-[10px] text-emerald-600 font-medium">{r.co2Saved} kg</span></td><td className="p-2"><span className={"lmo-route-status inline-flex px-1.5 py-0.5 rounded text-[10px] font-medium " + (r.status === "active" ? "bg-emerald-100 text-emerald-700" : r.status === "delayed" ? "bg-amber-100 text-amber-700" : r.status === "cancelled" ? "bg-red-100 text-red-700" : "bg-gray-100 text-gray-600")}>{r.status}</span></td></tr>)}</tbody></table>')
b('      </div>')
