b('    </div>')
b('  )')
b('')
b('  const tab4 = (')
b('    <div className="space-y-4">')
b('      <ModuleBreadcrumb items={[{ label: "Logistics" }, { label: "Last Mile" }, { label: "Analytics" }]}/>')
b('      <div className="grid grid-cols-2 md:grid-cols-4 gap-3">')
b('        <Card className="lmo-insight-card glass-subtle"><CardContent className="p-3 text-center"><div className="text-2xl font-bold text-amber-600">{"\\u20b9"}{deliveries.reduce((s, d) => s + d.cost, 0).toLocaleString()}</div><div className="text-[10px] text-muted-foreground mt-1">Total Delivery Cost</div></CardContent></Card>')
b('        <Card className="lmo-insight-card glass-subtle"><CardContent className="p-3 text-center"><div className="text-2xl font-bold text-emerald-600">{slaRate}%</div><div className="text-[10px] text-muted-foreground mt-1">SLA Achievement</div><div className="mt-2 h-1 rounded-full bg-gray-200"><div className="h-full rounded-full" style={{ width: slaRate + "%", backgroundColor: slaRate >= 95 ? TH.ok : TH.warn }}/></div></CardContent></Card>')
b('        <Card className="lmo-insight-card glass-subtle"><CardContent className="p-3 text-center"><div className="text-2xl font-bold text-blue-600">{fleet.filter(f => f.status === "active").length}</div><div className="text-[10px] text-muted-foreground mt-1">Vehicles Active Now</div></CardContent></Card>')
b('        <Card className="lmo-insight-card glass-subtle"><CardContent className="p-3 text-center"><div className="text-2xl font-bold text-violet-600">{routes.reduce((s, r) => s + r.co2Saved, 0)} kg</div><div className="text-[10px] text-muted-foreground mt-1">Total CO2 Saved</div></CardContent></Card>')
b('      </div>')
b('      <div className="grid grid-cols-1 md:grid-cols-2 gap-3">')
b('        <Card className="lmo-chart-card glass-subtle"><CardHeader className="pb-1"><CardTitle className="text-xs">Delivery Status Distribution</CardTitle></CardHeader><CardContent><PieChart width={300} height={200}><Pie data={DELIVERY_STATUS.map((s) => ({ name: s.replace(/_/g, " "), value: deliveries.filter(d => d.status === s).length }))} cx="50%" cy="50%" outerRadius={70} dataKey="value" label={({ name, percent }) => name + " " + (percent * 100).toFixed(0) + "%"} labelLine={false}>{DELIVERY_STATUS.map((_, i) => <Cell key={i} fill={PC[i % PC.length]}/>)}</Pie><Tooltip contentStyle={{ fontSize: 10 }}/></PieChart></CardContent></Card>')
b('        <Card className="lmo-chart-card glass-subtle"><CardHeader className="pb-1"><CardTitle className="text-xs">Vehicle Type Distribution</CardTitle></CardHeader><CardContent><PieChart width={300} height={200}><Pie data={VEHICLE_TYPES.map((v) => ({ name: v, value: fleet.filter(f => f.type === v).length }))} cx="50%" cy="50%" outerRadius={70} dataKey="value" label={({ name, percent }) => name + " " + (percent * 100).toFixed(0) + "%"} labelLine={false}>{VEHICLE_TYPES.map((_, i) => <Cell key={i} fill={PC[(i + 2) % PC.length]}/>)}</Pie><Tooltip contentStyle={{ fontSize: 10 }}/></PieChart></CardContent></Card>')
b('      </div>')
b('    </div>')
b('  )')
b('')
b('  const tabs = [')
b('    { key: "dashboard", label: "Dashboard", icon: <BarChart3 className="w-3.5 h-3.5" />, content: tab0 },')
