b('    { key: "fleet", label: "Fleet Manager", icon: <Truck className="w-3.5 h-3.5" />, content: tab2 },')
b('    { key: "routes", label: "Route Planner", icon: <Route className="w-3.5 h-3.5" />, content: tab3 },')
b('    { key: "analytics", label: "Analytics", icon: <TrendingUp className="w-3.5 h-3.5" />, content: tab4 }')
b('  ]')
b('')
b('  return (')
b('    <div className="space-y-4 p-4">')
b('      <PageHeader title="Last Mile Optimization Pro" description="End-to-end last mile delivery optimization with fleet management, route planning, real-time tracking, and SLA monitoring"/>')
b('      <div className="flex items-center gap-3 flex-wrap">')
b('        <div className="flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-amber-100 dark:bg-amber-900/30"><Truck className="w-3 h-3 text-amber-600"/><span className="text-[10px] font-semibold text-amber-700 dark:text-amber-300">{inTransit} In Transit</span></div>')
b('        <div className="flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-emerald-100 dark:bg-emerald-900/30"><CheckCircle2 className="w-3 h-3 text-emerald-600"/><span className="text-[10px] font-semibold text-emerald-700 dark:text-emerald-300">{slaRate}% SLA Rate</span></div>')
b('        <div className="flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-violet-100 dark:bg-violet-900/30"><Navigation className="w-3 h-3 text-violet-600"/><span className="text-[10px] font-semibold text-violet-700 dark:text-violet-300">{fleet.length} Vehicles | {routes.length} Routes</span></div>')
b('        <div className="flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-blue-100 dark:bg-blue-900/30"><Star className="w-3 h-3 text-blue-600"/><span className="text-[10px] font-semibold text-blue-700 dark:text-blue-300">{avgRating}/5 Rating</span></div>')
b('      </div>')
b('      <Tabs value={tab} onValueChange={setTab}>')
b('        <TabsList className="bg-gradient-to-r from-amber-500/10 to-red-500/10 p-0.5 h-9">')
b('          {tabs.map(t => <TabsTrigger key={t.key} value={t.key} className="text-xs gap-1.5 data-[state=active]:bg-amber-600 data-[state=active]:text-white">{t.icon}{t.label}</TabsTrigger>)}')
b('        </TabsList>')
b('        {tabs.map(t => tab === t.key && <div key={t.key} className="mt-3">{t.content}</div>)}')
b('      </Tabs>')
b('      <Sheet open={!!detail} onOpenChange={() => setDetail(null)}>')
b('        <SheetContent className="w-[420px] overflow-y-auto">')
b('          <SheetHeader><SheetTitle className="text-sm">Delivery Detail</SheetTitle></SheetHeader>')
b('          {detail && <div className="mt-4 space-y-3">')
b('            <div className="lmo-detail-header rounded-lg p-4 bg-gradient-to-br from-amber-500 to-red-600 text-white"><div className="text-lg font-bold">{String(detail.id)}</div><div className="text-xs opacity-80 mt-1">{String(detail.customer || detail.name || "Record")}</div></div>')
b('            {Object.entries(detail).filter(([k]) => k !== "id").map(([k, v]) => <div key={k} className="flex items-center justify-between py-1.5 border-b"><span className="text-[10px] text-muted-foreground capitalize">{k.replace(/_/g, " ")}</span><span className="text-xs font-medium">{typeof v === "number" ? v.toLocaleString() : String(v)}</span></div>)}')
b('          </div>}')
b('        </SheetContent>')
b('      </Sheet>')
b('    </div>')
b('  )')
b('}')

